import{_ as l,a0 as p,w as o,s as c,ao as h,I as t,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191113 How to install and Configure Postfix Mail Server on CentOS 8","title":"如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器","tag":"201911","desc":""},"relativePath":"201911/20191113 How to install and Configure Postfix Mail Server on CentOS 8.md","filePath":"[post].md"}'),d={name:"201911/20191113 How to install and Configure Postfix Mail Server on CentOS 8.md"};function r(g,s,k,f,u,b){const i=p("Link");return o(),c("div",null,[s[15]||(s[15]=h(`<h1 id="如何在-centos-8-上安裝和配置-postfix-郵件服務器" tabindex="-1">如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器 <a class="header-anchor" href="#如何在-centos-8-上安裝和配置-postfix-郵件服務器" aria-label="Permalink to “如何在 CentOS 8 上安裝和配置 Postfix 郵件服務器”">​</a></h1><p>Postfix 是一個自由開源的 MTA（郵件傳輸代理），用於在 Linux 系統上路由或傳遞電子郵件。在本指南中，你將學習如何在 CentOS 8 上安裝和配置 Postfix。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-configure-Postfx-Server-CentOS8.jpg" alt="Install-configure-Postfx-Server-CentOS8"></p><p>實驗室設置：</p><ul><li>系統：CentOS 8 服務器</li><li>IP 地址：192.168.1.13</li><li>主機名：server1.crazytechgeek.info（確保域名指向服務器的 IP）</li></ul><h3 id="步驟-1-更新系統" tabindex="-1">步驟 1）更新系統 <a class="header-anchor" href="#步驟-1-更新系統" aria-label="Permalink to “步驟 1）更新系統”">​</a></h3><p>第一步是確保系統軟件包是最新的。為此，請按如下所示更新系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf update</span></span></code></pre></div><p>繼續之前，還請確保不存在其他 MTA（如 Sendmail），因為這將導致與 Postfix 配置衝突。例如，要刪除 Sendmail，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf remove sendmail</span></span></code></pre></div><h3 id="步驟-2-設置主機名並更新-etc-hosts" tabindex="-1">步驟 2）設置主機名並更新 /etc/hosts <a class="header-anchor" href="#步驟-2-設置主機名並更新-etc-hosts" aria-label="Permalink to “步驟 2）設置主機名並更新 /etc/hosts”">​</a></h3><p>使用下面的 <code>hostnamectl</code> 命令在系統上設置主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hostnamectl set-hostname server1.crazytechgeek.info</span></span>
<span class="line"><span># exec bash</span></span></code></pre></div><p>此外，你需要在 <code>/etc/hosts</code> 中添加系統的主機名和 IP：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vim /etc/hosts</span></span>
<span class="line"><span>192.168.1.13   server1.crazytechgeek.info</span></span></code></pre></div><p>保存並退出文件。</p><h3 id="步驟-3-安裝-postfix-郵件服務器" tabindex="-1">步驟 3）安裝 Postfix 郵件服務器 <a class="header-anchor" href="#步驟-3-安裝-postfix-郵件服務器" aria-label="Permalink to “步驟 3）安裝 Postfix 郵件服務器”">​</a></h3><p>驗證系統上沒有其他 MTA 在運行後，運行以下命令安裝 Postfix：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install postfix</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-Postfix-Centos8.png" alt="Install-Postfix-Centos8"></p><h3 id="步驟-4-啓動並啓用-postfix-服務" tabindex="-1">步驟 4）啓動並啓用 Postfix 服務 <a class="header-anchor" href="#步驟-4-啓動並啓用-postfix-服務" aria-label="Permalink to “步驟 4）啓動並啓用 Postfix 服務”">​</a></h3><p>成功安裝 Postfix 後，運行以下命令啓動並啓用 Postfix 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start postfix</span></span>
<span class="line"><span># systemctl enable postfix</span></span></code></pre></div><p>要檢查 Postfix 狀態，請運行以下 <code>systemctl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status postfix</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Start-Postfix-check-status-centos8.png" alt="Start-Postfix-check-status-centos8"></p><p>太好了，我們已經驗證了 Postfix 已啓動並正在運行。接下來，我們將配置 Postfix 從本地發送郵件到我們的服務器。</p><h3 id="步驟-5-安裝-mailx-郵件客户端" tabindex="-1">步驟 5）安裝 mailx 郵件客户端 <a class="header-anchor" href="#步驟-5-安裝-mailx-郵件客户端" aria-label="Permalink to “步驟 5）安裝 mailx 郵件客户端”">​</a></h3><p>在配置 Postfix 服務器之前，我們需要安裝 <code>mailx</code>，要安裝它，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install mailx</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-Mailx-CentOS8.png" alt="Install-Mailx-CentOS8"></p><h3 id="步驟-6-配置-postfix-郵件服務器" tabindex="-1">步驟 6）配置 Postfix 郵件服務器 <a class="header-anchor" href="#步驟-6-配置-postfix-郵件服務器" aria-label="Permalink to “步驟 6）配置 Postfix 郵件服務器”">​</a></h3><p>Postfix 的配置文件位於 <code>/etc/postfix/main.cf</code> 中。我們需要對配置文件進行一些修改，因此請使用你喜歡的文本編輯器將其打開：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/postfix/main.cf</span></span></code></pre></div><p>更改以下幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>myhostname = server1.crazytechgeek.info</span></span>
<span class="line"><span>mydomain = crazytechgeek.info</span></span>
<span class="line"><span>myorigin = $mydomain</span></span>
<span class="line"><span>## 取消註釋並將 inet_interfaces 設置為 all##</span></span>
<span class="line"><span>inet_interfaces = all</span></span>
<span class="line"><span>## 更改為 all ##</span></span>
<span class="line"><span>inet_protocols = all</span></span>
<span class="line"><span>## 註釋 ##</span></span>
<span class="line"><span>#mydestination = $myhostname, localhost.$mydomain, localhost</span></span>
<span class="line"><span>## 取消註釋 ##</span></span>
<span class="line"><span>mydestination = $myhostname, localhost.$mydomain, localhost, $mydomain</span></span>
<span class="line"><span>## 取消註釋並添加 IP 範圍 ##</span></span>
<span class="line"><span>mynetworks = 192.168.1.0/24, 127.0.0.0/8</span></span>
<span class="line"><span>## 取消註釋 ##</span></span>
<span class="line"><span>home_mailbox = Maildir/</span></span></code></pre></div><p>完成後，保存並退出配置文件。重新啓動 postfix 服務以使更改生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart postfix</span></span></code></pre></div><h3 id="步驟-7-測試-postfix-郵件服務器" tabindex="-1">步驟 7）測試 Postfix 郵件服務器 <a class="header-anchor" href="#步驟-7-測試-postfix-郵件服務器" aria-label="Permalink to “步驟 7）測試 Postfix 郵件服務器”">​</a></h3><p>測試我們的配置是否有效，首先，創建一個測試用户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd postfixuser</span></span>
<span class="line"><span># passwd postfixuser</span></span></code></pre></div><p>接下來，運行以下命令，從本地用户 <code>pkumar</code> 發送郵件到另一個用户 <code>postfixuser</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># telnet localhost smtp</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span># telnet localhost 25</span></span></code></pre></div><p>如果未安裝 telnet 服務，那麼可以使用以下命令進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install telnet -y</span></span></code></pre></div><p>如前所述運行命令時，應獲得如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# telnet localhost 25</span></span>
<span class="line"><span>Trying 127.0.0.1...</span></span>
<span class="line"><span>Connected to localhost.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>220 server1.crazytechgeek.info ESMTP Postfix</span></span></code></pre></div><p>上面的結果確認與 postfix 郵件服務器的連接正常。接下來，輸入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ehlo localhost</span></span></code></pre></div><p>輸出看上去像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>250-server1.crazytechgeek.info</span></span>
<span class="line"><span>250-PIPELINING</span></span>
<span class="line"><span>250-SIZE 10240000</span></span>
<span class="line"><span>250-VRFY</span></span>
<span class="line"><span>250-ETRN</span></span>
<span class="line"><span>250-STARTTLS</span></span>
<span class="line"><span>250-ENHANCEDSTATUSCODES</span></span>
<span class="line"><span>250-8BITMIME</span></span>
<span class="line"><span>250-DSN</span></span>
<span class="line"><span>250 SMTPUTF8</span></span></code></pre></div><p>接下來，運行橙色高亮的命令，例如 <code>mail from</code>、<code>rcpt to</code>、<code>data</code>，最後輸入 <code>quit</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mail from:&lt;pkumar&gt;</span></span>
<span class="line"><span>250 2.1.0 Ok</span></span>
<span class="line"><span>rcpt to:&lt;postfixuser&gt;</span></span>
<span class="line"><span>250 2.1.5 Ok</span></span>
<span class="line"><span>data</span></span>
<span class="line"><span>354 End data with &lt;CR&gt;&lt;LF&gt;.&lt;CR&gt;&lt;LF&gt;</span></span>
<span class="line"><span>Hello, Welcome to my mailserver (Postfix)</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>250 2.0.0 Ok: queued as B56BF1189BEC</span></span>
<span class="line"><span>quit</span></span>
<span class="line"><span>221 2.0.0 Bye</span></span>
<span class="line"><span>Connection closed by foreign host</span></span></code></pre></div><p>完成 <code>telnet</code> 命令可從本地用户 <code>pkumar</code> 發送郵件到另一個本地用户 <code>postfixuser</code>，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Send-email-with-telnet-centos8.png" alt="Send-email-with-telnet-centos8"></p><p>如果一切都按計劃進行，那麼你應該可以在新用户的家目錄中查看發送的郵件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls /home/postfixuser/Maildir/new</span></span>
<span class="line"><span>1573580091.Vfd02I20050b8M635437.server1.crazytechgeek.info</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>要閲讀郵件，只需使用 cat 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /home/postfixuser/Maildir/new/1573580091.Vfd02I20050b8M635437.server1.crazytechgeek.info</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Read-postfix-email-linux.png" alt="Read-postfix-email-linux"></p><h3 id="postfix-郵件服務器日誌" tabindex="-1">Postfix 郵件服務器日誌 <a class="header-anchor" href="#postfix-郵件服務器日誌" aria-label="Permalink to “Postfix 郵件服務器日誌”">​</a></h3><p>Postfix 郵件服務器郵件日誌保存在文件 <code>/var/log/maillog</code> 中，使用以下命令查看實時日誌，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/maillog</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/postfix-maillogs-centos8.png" alt="postfix-maillogs-centos8"></p><h3 id="保護-postfix-郵件服務器" tabindex="-1">保護 Postfix 郵件服務器 <a class="header-anchor" href="#保護-postfix-郵件服務器" aria-label="Permalink to “保護 Postfix 郵件服務器”">​</a></h3><p>建議始終確保客户端和 Postfix 服務器之間的通信安全，這可以使用 SSL 證書來實現，它們可以來自受信任的權威機構或自簽名證書。在本教程中，我們將使用 <code>openssl</code> 命令生成用於 Postfix 的自簽名證書，</p><p>我假設 <code>openssl</code> 已經安裝在你的系統上，如果未安裝，請使用以下 <code>dnf</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install openssl -y</span></span></code></pre></div><p>使用下面的 <code>openssl</code> 命令生成私鑰和 CSR（證書籤名請求）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openssl req -nodes -newkey rsa:2048 -keyout mail.key -out mail.csr</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Postfix-Key-CSR-CentOS8.png" alt="Postfix-Key-CSR-CentOS8"></p><p>現在，使用以下 openssl 命令生成自簽名證書：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openssl x509 -req -days 365 -in mail.csr -signkey mail.key -out mail.crt</span></span>
<span class="line"><span>Signature ok</span></span>
<span class="line"><span>subject=C = IN, ST = New Delhi, L = New Delhi, O = IT, OU = IT, CN = server1.crazytechgeek.info, emailAddress = root@linuxtechi</span></span>
<span class="line"><span>Getting Private key</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>現在將私鑰和證書文件複製到 <code>/etc/postfix</code> 目錄下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp mail.key mail.crt /etc/postfix</span></span></code></pre></div><p>在 Postfix 配置文件中更新私鑰和證書文件的路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/postfix/main.cf</span></span>
<span class="line"><span>………</span></span>
<span class="line"><span>smtpd_use_tls = yes</span></span>
<span class="line"><span>smtpd_tls_cert_file = /etc/postfix/mail.crt</span></span>
<span class="line"><span>smtpd_tls_key_file = /etc/postfix/mail.key</span></span>
<span class="line"><span>smtpd_tls_security_level = may</span></span>
<span class="line"><span>………</span></span></code></pre></div><p>重啓 Postfix 服務以使上述更改生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart postfix</span></span></code></pre></div><p>讓我們嘗試使用 <code>mailx</code> 客户端將郵件發送到內部本地域和外部域。</p><p>從 <code>pkumar</code> 發送內部本地郵件到 <code>postfixuser</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;test email&quot; | mailx -s &quot;Test email from Postfix MailServer&quot; -r root@linuxtechi root@linuxtechi</span></span></code></pre></div><p>使用以下命令檢查並閲讀郵件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /home/postfixuser/Maildir/new/</span></span>
<span class="line"><span># ll</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>-rw-------. 1 postfixuser postfixuser 476 Nov 12 17:34 1573580091.Vfd02I20050b8M635437.server1.crazytechgeek.info</span></span>
<span class="line"><span>-rw-------. 1 postfixuser postfixuser 612 Nov 13 02:40 1573612845.Vfd02I20050bbM466643.server1.crazytechgeek.info</span></span>
<span class="line"><span># cat 1573612845.Vfd02I20050bbM466643.server1.crazytechgeek.info</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Read-Postfixuser-Email-CentOS8.png" alt="Read-Postfixuser-Email-CentOS8"></p><p>從 <code>postfixuser</code> 發送郵件到外部域（<code>root@linuxtechi.com</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;External Test email&quot; | mailx -s &quot;Postfix MailServer&quot; -r root@linuxtechi root@linuxtechi</span></span></code></pre></div><p>注意：如果你的 IP 沒有被任何地方列入黑名單，那麼你發送到外部域的郵件將被髮送，否則它將被退回，並提示你的 IP 被 spamhaus 之類的資料庫列入黑名單。</p><h3 id="檢查-postfix-郵件隊列" tabindex="-1">檢查 Postfix 郵件隊列 <a class="header-anchor" href="#檢查-postfix-郵件隊列" aria-label="Permalink to “檢查 Postfix 郵件隊列”">​</a></h3><p>使用 <code>mailq</code> 命令列出隊列中的郵件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mailq</span></span>
<span class="line"><span>Mail queue is empty</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>完成！我們的 Postfix 配置正常工作了！目前就這樣了。我們希望你覺得本教程有見地，並且你可以輕鬆地設置本地 Postfix 服務器。</p><hr>`,93)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/install-configure-postfix-mailserver-centos-8/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/install-configure-postfix-mailserver-centos-8/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/james/"},{default:n(()=>[...s[2]||(s[2]=[a("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(d,[["render",r]]);export{y as __pageData,C as default};
